WITH src AS (SELECT * FROM order_items WHERE product_id IS NULL AND order_id IN (6, 25, 27, 40)), order_items_stats AS (SELECT CASE WHEN unit_price >= 430 THEN 'high' WHEN unit_price >= 60 THEN 'mid' ELSE 'low' END AS unit_price_bucket, SUM(unit_price * quantity) AS revenue, SUM(quantity) AS total_quantity FROM src GROUP BY CASE WHEN unit_price >= 430 THEN 'high' WHEN unit_price >= 60 THEN 'mid' ELSE 'low' END) SELECT * FROM order_items_stats ORDER BY 3;
